 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The painted five-cell horizontal sample is the pattern to stamp.
    sample = None
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start == 5:
                sample = (r, start, row[start:c][:])
                break
        if sample is not None:
            break
    if sample is None:
        return out

    sr, sc, pattern = sample
    colors = set(pattern)
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] not in colors
               and (r, c) != (sr, sc)]
    for r, c in markers:
        left = c - len(pattern) // 2
        for i, value in enumerate(pattern):
            x = left + i
            if 0 <= x < w:
                out[r][x] = value
    return out
